(async()=>{'use strict';
const $=id=>document.getElementById(id),status=t=>$('status').textContent=t;
let originals=[],drafts={},current,db,urls=[];
const isVideo=p=>/\.(mp4|webm)$/i.test(p),accepted=['image/jpeg','image/png','image/webp','image/avif','video/mp4','video/webm'];
function transaction(mode,fn){return new Promise((resolve,reject)=>{const t=db.transaction('drafts',mode);fn(t.objectStore('drafts'));t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)})}
function readAll(){return new Promise((resolve,reject)=>{const q=db.transaction('drafts').objectStore('drafts').getAll();q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
function objectUrl(blob){const u=URL.createObjectURL(blob);urls.push(u);return u}
function render(){urls.forEach(URL.revokeObjectURL);urls=[];const media=document.createElement(isVideo(current.src)?'video':'img');media.src=current.file?objectUrl(current.file):'../'+current.src;media.style.objectFit=current.fit;media.setAttribute('aria-label',current.alt);if(media.tagName==='VIDEO'){media.controls=true;media.playsInline=true;media.preload='metadata';media.poster=current.posterFile?objectUrl(current.posterFile):'../'+current.poster}else media.alt=current.alt;$('preview').replaceChildren(media);$('alt').value=current.alt;$('caption').value=current.caption||'';$('fit').value=current.fit;$('usage').textContent='Changing this placement updates every page that uses it after the change is applied and the website rebuilt.'}
function fields(){current.alt=$('alt').value.trim();current.caption=$('caption').value;current.fit=$('fit').value}
function choose(){const base=originals.find(x=>x.id===$('placement').value);current={...(drafts[base.id]||base)};$('upload').value='';$('poster').value='';render();status(drafts[base.id]?'Saved browser draft loaded.':'Current website media loaded.')}
async function ingest(file,poster=false){try{if(!file)return;if(!accepted.includes(file.type)||(poster&&!file.type.startsWith('image/')))throw Error('Choose a supported '+(poster?'image.':'image or video.'));if(file.size>25000000)throw Error('Use a file smaller than 25 MB.');const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/avif':'avif','video/mp4':'mp4','video/webm':'webm'}[file.type];const path='images/uploads/'+crypto.randomUUID()+'.'+ext;fields();if(poster){current.poster=path;current.posterFile=file}else{current.file=file;current.src=path;if(file.type.startsWith('image/')){const bitmap=await createImageBitmap(file);current.width=bitmap.width;current.height=bitmap.height;bitmap.close()}else if(!current.poster){const original=originals.find(x=>x.id===current.id);if(!isVideo(original.src))current.poster=original.src}}render();status('Replacement ready to review. Save the browser draft to keep it.')}catch(e){status(e.message)}}
try{const response=await fetch('media.json');if(!response.ok)throw Error('Could not load media.');originals=(await response.json()).items;db=await new Promise((resolve,reject)=>{const q=indexedDB.open('visioncraft-media-drafts-v1',1);q.onupgradeneeded=()=>q.result.createObjectStore('drafts',{keyPath:'id'});q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)});for(const d of await readAll())drafts[d.id]=d;for(const m of originals){const o=document.createElement('option');o.value=m.id;o.textContent=m.label;$('placement').append(o)}choose()}catch(e){status('Editor unavailable: '+e.message);return}
$('placement').onchange=choose;$('upload').onchange=e=>ingest(e.target.files[0]);$('poster').onchange=e=>ingest(e.target.files[0],true);$('fit').onchange=()=>{fields();render()};
for(const name of ['dragenter','dragover'])$('drop').addEventListener(name,e=>{e.preventDefault();$('drop').classList.add('over')});$('drop').ondragleave=()=>$('drop').classList.remove('over');$('drop').ondrop=e=>{e.preventDefault();$('drop').classList.remove('over');ingest(e.dataTransfer.files[0])};
$('save').onclick=async()=>{fields();if(!current.alt)return status('Add an accessible description first.');if(isVideo(current.src)&&!current.poster)return status('Add a poster image for this video.');try{await transaction('readwrite',s=>s.put(current));drafts[current.id]={...current};status('Saved in this browser. The website has not been changed.')}catch{status('Could not save this draft. Your browser storage may be full.')}};
$('restore').onclick=async()=>{try{await transaction('readwrite',s=>s.delete(current.id));delete drafts[current.id];choose()}catch{status('Could not restore the placement.')}};
const base64=blob=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob)});
$('export').onclick=async()=>{const entries=Object.values(drafts);if(!entries.length)return status('Save a browser draft first.');$('export').disabled=true;try{const assets=[],items=[];for(const entry of entries){const {file,posterFile,...m}=entry;items.push(m);if(file)assets.push({path:m.src,data:await base64(file)});if(posterFile)assets.push({path:m.poster,data:await base64(posterFile)})}const blob=new Blob([JSON.stringify({version:1,items,assets})],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='visioncraft-media-update.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('Exported saved drafts. Share this update file to apply it to the website; nothing has been published.')}catch{status('Export failed. Try a smaller file.')}finally{$('export').disabled=false}};
})();
